package events

import (
	"errors"
	"strings"
	"testing"
	"time"
)

// ampPayloadSize reports the MarshalBatch length of a one-event batch whose
// message is n ampersands. In the save format '&' escapes to '&amp;', so each
// character costs five saved bytes; the event uses no labels and stable short
// fields so the fixed overhead is the only other term.
func ampEvent(id string, amps int, at time.Time) Event {
	return Event{
		ID:       id,
		Service:  "svc",
		Severity: "info",
		Message:  strings.Repeat("&", amps),
		At:       at,
	}
}

// payloadOverhead returns the fixed encoded length of a one-event batch with
// an empty message: payload(n) == overhead + 5n for '&'-filled messages.
func payloadOverhead(t *testing.T, at time.Time) int {
	t.Helper()
	empty, err := MarshalBatch([]Event{ampEvent("probe", 0, at)})
	if err != nil {
		t.Fatalf("marshal probe: %v", err)
	}
	return len(empty)
}

// TestIngestCapacityExactLimitAccepted proves the boundary is inclusive: a
// batch encoding to exactly MaxBatchPayloadBytes is saved, while a single
// extra escaped character makes it an OversizeBatchError.
func TestIngestCapacityExactLimitAccepted(t *testing.T) {
	tl := NewTimeline()
	base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)

	// Pad the id until the fixed overhead makes the limit reachable exactly
	// with whole '&' characters (each worth five saved bytes).
	id := "exact-limit"
	overhead := payloadOverhead(t, base)
	for pad := 0; (overhead+pad)%5 != MaxBatchPayloadBytes%5; pad++ {
		id += "x"
		overhead = payloadOverheadWithID(t, id, base)
	}
	amps := (MaxBatchPayloadBytes - overhead) / 5
	if amps <= 0 {
		t.Fatalf("test setup: overhead %d leaves no room", overhead)
	}

	atLimit := ampEvent(id, amps, base)
	encoded, err := MarshalBatch([]Event{atLimit})
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if len(encoded) != MaxBatchPayloadBytes {
		t.Fatalf("setup: encoded %d bytes, want %d", len(encoded), MaxBatchPayloadBytes)
	}

	committed := false
	res, err := tl.Ingest([]Event{atLimit}, func(created []Event) error {
		committed = true
		return nil
	})
	if err != nil {
		t.Fatalf("batch at exactly the limit must be accepted: %v", err)
	}
	if !committed || res.Created != 1 {
		t.Fatalf("exact-limit batch not committed: %+v committed=%v", res, committed)
	}

	// One more '&' pushes the saved content five bytes past the limit.
	over := ampEvent("over-limit", amps+1, base)
	encoded, _ = MarshalBatch([]Event{over})
	if len(encoded) <= MaxBatchPayloadBytes {
		t.Fatalf("setup: over batch encodes to %d", len(encoded))
	}
	var oversized *OversizeBatchError
	_, err = tl.Ingest([]Event{over}, func(created []Event) error {
		t.Fatalf("oversize batch must not reach the commit hook")
		return nil
	})
	if !errors.As(err, &oversized) {
		t.Fatalf("want OversizeBatchError, got %v", err)
	}
