// an empty message: payload(n) == overhead + 5n for '&'-filled messages.
func payloadOverhead(t *testing.T, at time.Time) int {
	t.Helper()
	empty, err := MarshalBatch([]Event{ampEvent("probe", 0, at)})
	if err != nil {
