		t.Fatalf("setup: encoded %d bytes, want %d", len(encoded), MaxBatchPayloadBytes)
	}

	committed := false
	res, err := tl.Ingest([]Event{atLimit}, func(created []Event) error {
		committed = true
		return nil
	})
	if err != nil {
