	// succeeds with no conflict and no restart.
	small := ampEvent("over-limit", 4, base.Add(time.Second))
	res, err = tl.Ingest([]Event{small}, nil)
	if err != nil {
		t.Fatalf("rejected id must remain usable: %v", err)
	}
	if res.Created != 1 {
		t.Fatalf("later small batch: %+v", res)
	}
}

